//! Exact original expiry four output phases and direct-before-outer ALLOW traces.
//! Two current immutable selected source visits; no Tree/semantic model or EOF authority in DATA.
use crate::{captured_api_pages as fund,captured_generator_budget::Budget,captured_raw_file::{Config,RawPolicyViews},captured_reactive_reads::Failure,captured_allow_annotations::Operation,reactive_raw_policy_pages::RawPolicyPages,lint::AllowUse};
use std::{io,sync::Arc,collections::BTreeSet};
pub fn metadata()->&'static crate::lint::Meta{static M:std::sync::OnceLock<crate::lint::Meta>=std::sync::OnceLock::new();M.get_or_init(||crate::dm::sys::module_metadata(&crate::dm::sys::SysModule{name:crate::allow_registry_fields::sys_expiry::SCOPE_MODULE_NAME,rules:crate::allow_registry_fields::sys_expiry::RULES,..crate::dm::sys::SysModule::DEFAULT},crate::lint::ScanKind::Tree))}
struct Facts{relative:String,compares:Vec<usize>,writes:crate::expiry_policy::Writes,at:Vec<usize>,extra:fund::ApiData}
struct Phase{budget:Arc<Budget>,complete:bool}impl Drop for Phase{fn drop(&mut self){if !self.complete{self.budget.keep_failed_scratch()}}}
fn oom(b:&Budget)->Failure{b.deny();Failure::Operational(io::ErrorKind::OutOfMemory.into())}
fn selected(config:&Config,relative:&str)->bool{!config.policy_path_exempt("sys/expiry","sys",relative)}
fn direct_kept(views:&RawPolicyViews<'_>,line:usize,extra:&mut fund::ApiData,root:&Budget,poll:&dyn Fn()->io::Result<()>)->Result<bool,Failure>{let file=views.source_file()?;let local=views.allocation_budget(root);let Some(kept)=crate::allow::kept_using(file,line,"cooldown",&mut Operation{budget:local,poll})? else{return Ok(false)};let line=u32::try_from(kept.line).map_err(|_|Failure::from("expiry direct ALLOW coordinate overflow"))?;let code=kept.code.unwrap_or_default();if !extra.allow_used.iter().any(|u|u.rel==file.rel&&u.line==line&&u.name=="cooldown"&&u.code==code){fund::row(root,poll,&mut extra.allow_used)?;extra.allow_used.push(AllowUse{rel:fund::own(root,poll,&file.rel)?,line,name:fund::own(root,poll,"cooldown")?,code:fund::own(root,poll,&code)?});}if !extra.digests.contains_key(file.rel.as_str()){fund::node(root)?;extra.digests.insert(fund::own(root,poll,&file.rel)?,crate::captured_raw_file::source_allow_digest(file));}fund::checked(local,poll)?;Ok(true)}
fn append(data:&mut fund::ApiData,mut from:fund::ApiData,root:&Budget,poll:&dyn Fn()->io::Result<()>)->Result<(),Failure>{let mut uses=Vec::new();for u in from.allow_used.drain(..){fund::checked(root,poll)?;if !data.allow_used.contains(&u)&&!uses.contains(&u){fund::row(root,poll,&mut uses)?;uses.push(u);}}from.allow_used=uses;fund::append(data,from,root,poll)}
pub fn collect(pages:&dyn RawPolicyPages,config:&Config,root:&Arc<Budget>,poll:&dyn Fn()->io::Result<()>)->Result<fund::ApiData,Failure>{fund::checked(root,poll)?;let mut phase=Phase{budget:Budget::scoped_temporaries(root).map_err(|_|oom(root))?,complete:false};let b=&phase.budget;let pending=(||{
 let mut facts=Vec::new();if !pages.for_each(&mut|relative,views|{fund::checked(b,poll)?;if !selected(config,relative){return Ok(true)}let file=views.source_file()?;if relative!=file.rel{return Err("expiry index original relative path differs".into())}let local=views.allocation_budget(root);let mut keep=Operation{budget:b,poll};let mut temp=Operation{budget:local,poll};let mut extra=fund::empty();let compares=crate::expiry_policy::pass_compares_using(file,None,&mut keep,&mut|line,_|direct_kept(&views,line,&mut extra,root,poll))?;let writes=crate::expiry_policy::pass_writes_using(file,&mut keep,&mut temp)?;let at=crate::expiry_policy::pass_at_writes_using(file,&mut keep,&mut temp)?;fund::row(b,poll,&mut facts)?;facts.push(Facts{relative:fund::own(b,poll,relative)?,compares,writes,at,extra});fund::checked(local,poll)?;Ok(true)})?{return Err("expiry complete original facts stopped before EOF".into())}
 b.charge(facts.len().checked_mul(4*std::mem::size_of::<Facts>()).and_then(|n|n.checked_add(128)).ok_or_else(||oom(b))?).map_err(|_|oom(b))?;facts.sort_by(|a,b|a.relative.cmp(&b.relative));let mut declared=BTreeSet::new();for fact in &facts{for name in &fact.writes.declared{fund::checked(b,poll)?;if !declared.contains(name.as_str()){fund::node(b)?;declared.insert(fund::own(b,poll,name)?);}}}
 let mut batches=Vec::new();if !pages.for_each(&mut|relative,views|{fund::checked(b,poll)?;if !selected(config,relative){return Ok(true)}let row=facts.binary_search_by(|row|row.relative.as_str().cmp(relative)).map_err(|_|Failure::from("expiry selected source absent from original facts"))?;let fact=&facts[row];let mut groups:[Vec<(&'static str,usize)>;4]=std::array::from_fn(|_|Vec::new());for line in &fact.compares{fund::row(b,poll,&mut groups[0])?;groups[0].push(("world_time_expiry",*line));}for line in &fact.writes.writes{fund::row(b,poll,&mut groups[1])?;groups[1].push(("world_time_write",*line));}for(line,name)in &fact.writes.uses{fund::checked(b,poll)?;if !declared.contains(name.as_str()){fund::row(b,poll,&mut groups[2])?;groups[2].push(("expiry_undeclared",*line));}}for line in &fact.at{fund::row(b,poll,&mut groups[3])?;groups[3].push(("world_time_write",*line));}let mut output=Vec::new();fund::reserve_append(b,poll,&mut output,4)?;for group in groups{output.push(crate::captured_sys_fields_pages::record_rows_borrowed(&views,group,&[],&[],root,poll)?);}fund::row(b,poll,&mut batches)?;batches.push((fund::own(b,poll,relative)?,output));Ok(true)})?{return Err("expiry selected original report stopped before EOF".into())}
 b.charge(batches.len().checked_mul(4*std::mem::size_of::<(String,Vec<fund::ApiData>)>()).and_then(|n|n.checked_add(128)).ok_or_else(||oom(b))?).map_err(|_|oom(b))?;batches.sort_by(|a,b|a.0.cmp(&b.0));let mut data=fund::empty();for fact in facts{append(&mut data,fact.extra,root,poll)?;}for phase in 0..4{for(_,groups)in &mut batches{fund::checked(b,poll)?;let group=std::mem::replace(&mut groups[phase],fund::empty());append(&mut data,group,root,poll)?;}}fund::checked(b,poll)?;Ok(data)
})();if matches!(&pending,Err(Failure::Operational(_))){return pending}fund::checked(root,poll)?;phase.complete=pending.is_ok();drop(phase);pending}
